import{_ as o,l as i,o as a,c as s,v as t,p as n,x as l,d as p,i as P,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"困惑度评测的陷阱","description":"","frontmatter":{"title":"困惑度评测的陷阱","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/perplexity-eval-pitfalls.md","filePath":"llm/perplexity-eval-pitfalls.md","lastUpdated":1789023840000}'),h={name:"llm/perplexity-eval-pitfalls.md"};function E(m,e,B,_,L,c){const r=i("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="困惑度评测的陷阱" tabindex="-1">困惑度评测的陷阱 <a class="header-anchor" href="#困惑度评测的陷阱" aria-label="Permalink to &quot;困惑度评测的陷阱&quot;">​</a></h1><div class="epigraph"><p>困惑度是词表与分词器上的交叉熵指数，不是「懂多少」的通用单位。换一套 BPE，同一个模型可以换一张完全不同的榜。</p><footer>—— 对照 Jelinek 的经典定义；分词器耦合见后续对数似然评测课</footer></div><p><a href="/llm/weight-sharing-compress">上一课</a>把压缩课序收到权重共享。压缩报告里常把困惑度（perplexity, PPL）当「量化没把模型打坏」的证据。本课打开评测进阶：PPL 作为<strong>能力数字</strong>有哪些陷阱。缺口不是再推交叉熵，而是：发布声明若写成「PPL 更低所以更强」，仪器已经选错。后课对数似然对生成式评测默认你已知道 PPL 不能单独签发能力。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PPL 是 \\(2^{H}\\) 或 \\(e^{H}\\)，其中 \\(H\\) 是每个 token 的平均负对数似然。它忠实于语言建模目标，因此对训练损失、数据域、<a href="/llm/bpe-merge-rule">分词器</a> 都敏感。换词表、换预分词、是否把标点粘在词上，都会改 token 数与每个 token 的难度，PPL 随之动，模型权重可以一动不动。跨模型比 PPL，等于在比两套不同的计数单位。</p><p>第二陷阱是域。在维基上低、在对话上高，只说明预训练域，不说明指令遵循或解题。第三陷阱是与生成质量脱节：Holtzman 等人已说明，低 PPL 的极大似然解码会退化成重复；用户要的是可接受的样本，不是测试集上的指数损失。</p><p><span class="marginnote">压缩与蒸馏课用 PPL 当<strong>同一分词器、同一验证集</strong>上的回归探针，这是合法的。非法的是拿它去横比不同词表的基座，或用它代理 MMLU。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>合法用法：固定 tokenizer、固定验证文档、固定是否含特殊符号，报告平均负对数似然（nats 或 bits/byte 比 PPL 更可移植）。bits/byte 把长度归一到字节，减轻词表宽度作弊。非法用法：在聊天模板打开的模型上对裸语料算 PPL；在指令模型上对预训练 holdout 报 PPL 并声称对齐没有损伤——模板本身就改了条件分布。</p><p>发布时若必须报 PPL，同时报：词表、字节级损失、验证域。能力声明改走任务评测。</p>',10)),(a(),n(d,null,{default:l(()=>[P(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20TXT%5B%22%E5%90%8C%E4%B8%80%E6%AE%B5%E6%96%87%E6%9C%AC%22%5D%20--%3E%20TOK%5B%22%E5%88%86%E8%AF%8D%E5%99%A8%20A%20%2F%20B%22%5D%0A%20%20TOK%20--%3E%20NLL%5B%22token%20%E8%B4%9F%E5%AF%B9%E6%95%B0%E4%BC%BC%E7%84%B6%22%5D%0A%20%20NLL%20--%3E%20PPL%5B%22PPL%22%5D%0A%20%20TOK%20--%3E%20BB%5B%22bits%2Fbyte%22%5D%0A%20%20PPL%20--%3E%20BAD%5B%22%E8%B7%A8%E8%AF%8D%E8%A1%A8%E4%B8%8D%E5%8F%AF%E6%AF%94%22%5D%0A%20%20BB%20--%3E%20OK%5B%22%E9%95%BF%E5%BA%A6%E5%8D%95%E4%BD%8D%E5%AF%B9%E9%BD%90%22%5D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>softmax 在词表上归一。大词表把概率质量摊到更多原子上，每个 token 更「难」，但一段话的 token 更少；小词表相反。PPL 按 token 平均，奖励切得碎的系统。bits/byte 按底层 UTF-8 平均，比较的是对同一字节串的压缩率，更接近「这个模型对这份语料的编码效率」。</p><p>PPL 与开放生成还隔着解码器：温度、截断、停止符都不进损失。损失好只约束教师强迫分布，不约束你实际画出的那一条路径。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不废除验证损失。训练曲线、过拟合、量化退化，仍应看同一仪器上的 NLL。下一课把「看选项的对数似然」和「生成后再抽答案」拆开——那是另一类被 PPL 思维带偏的评测。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PPL 绑定词表与域，不能当跨模型能力单位。</li><li>同一分词器上的 NLL / bits/byte 才是压缩与回归探针。</li><li>生成质量还取决于解码，低 PPL 不阻止退化。</li><li>出处：Jelinek 困惑度传统；Holtzman 等关于极大似然解码退化；字节级损失的工程实践。</li></ul>',7))])}const b=o(h,[["render",E]]);export{f as __pageData,b as default};
